import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as n,af as i}from"./chunks/mermaid.YsAH9es0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"Agent 运行期实践卡：任务语义、执行环境、协作与流量治理","description":"从阿里云《AI Agent Handbook》第 7—12 章提炼的 21 张可执行实践卡。每张卡给出要解决的问题、做法、前置条件、适用边界、失败模式、可验证指标、原文短引用，以及一人/小团队的降级做法；并区分阿里云团队主张/内部数据与可独立复现的做法。","frontmatter":{"title":"Agent 运行期实践卡：任务语义、执行环境、协作与流量治理","description":"从阿里云《AI Agent Handbook》第 7—12 章提炼的 21 张可执行实践卡。每张卡给出要解决的问题、做法、前置条件、适用边界、失败模式、可验证指标、原文短引用，以及一人/小团队的降级做法；并区分阿里云团队主张/内部数据与可独立复现的做法。","domain":"practice","tags":["agent","runtime","engineering"]},"headers":[],"relativePath":"zh/practice/agent-handbook/run.md","filePath":"zh/practice/agent-handbook/run.md","lastUpdated":1793277967000}'),l={name:"zh/practice/agent-handbook/run.md"};function e(s,t,a,g,d,c){return n(),r("div",null,[...t[0]||(t[0]=[i(`<h1 id="agent-运行期实践卡-第-7—12-章" tabindex="-1">Agent 运行期实践卡（第 7—12 章） <a class="header-anchor" href="#agent-运行期实践卡-第-7—12-章" aria-label="Permalink to &quot;Agent 运行期实践卡（第 7—12 章）&quot;">​</a></h1><p>面向一线研发与技术负责人。目标只有一个：把&quot;运行期&quot;——<strong>任务怎么跑、在哪跑、状态放哪、多个 Agent 怎么协作、流量怎么管</strong>——落成今天就能照做的步骤，并配上可验证的指标。</p><p>来源章节（阿里云《AI Agent Handbook》03-run）：</p><table tabindex="0"><thead><tr><th>卡</th><th>章节</th><th>链接</th></tr></thead><tbody><tr><td>卡1—卡5</td><td>第 10 章 Agent 异步任务与自动化流程</td><td><a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/03-run/%E7%AC%AC%2010%20%E7%AB%A0%20%20Agent%20%E5%BC%82%E6%AD%A5%E4%BB%BB%E5%8A%A1%E4%B8%8E%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%81%E7%A8%8B.md" target="_blank" rel="noreferrer">ch10</a></td></tr><tr><td>卡6—卡9</td><td>第 7 章 Agent 运行时与沙箱</td><td><a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/03-run/%E7%AC%AC%207%20%E7%AB%A0%20%20Agent%20%E8%BF%90%E8%A1%8C%E6%97%B6%E4%B8%8E%E6%B2%99%E7%AE%B1.md" target="_blank" rel="noreferrer">ch7</a></td></tr><tr><td>卡10—卡13</td><td>第 8 章 Agent 状态存储与语义资产</td><td><a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/03-run/%E7%AC%AC%208%20%E7%AB%A0%20Agent%20%E7%8A%B6%E6%80%81%E5%AD%98%E5%82%A8%E4%B8%8E%E8%AF%AD%E4%B9%89%E8%B5%84%E4%BA%A7.md" target="_blank" rel="noreferrer">ch8</a></td></tr><tr><td>卡14—卡17</td><td>第 12 章 Agent 分布式通信 / 第 11 章 Multi-Agent 协作与编排</td><td><a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/03-run/%E7%AC%AC%2012%20%E7%AB%A0%20Agent%20%E5%88%86%E5%B8%83%E5%BC%8F%E9%80%9A%E4%BF%A1.md" target="_blank" rel="noreferrer">ch12</a> / <a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/03-run/%E7%AC%AC%2011%E7%AB%A0%20%20Multi-Agent%20%E5%8D%8F%E4%BD%9C%E4%B8%8E%E7%BC%96%E6%8E%92.md" target="_blank" rel="noreferrer">ch11</a></td></tr><tr><td>卡18—卡21</td><td>第 9 章 AI 网关与统一流量治理</td><td><a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/03-run/%E7%AC%AC%209%20%E7%AB%A0%20%20AI%20%E7%BD%91%E5%85%B3%E4%B8%8E%E7%BB%9F%E4%B8%80%E6%B5%81%E9%87%8F%E6%B2%BB%E7%90%86.md" target="_blank" rel="noreferrer">ch9</a></td></tr></tbody></table><h2 id="_0-阅读约定" tabindex="-1">0. 阅读约定 <a class="header-anchor" href="#_0-阅读约定" aria-label="Permalink to &quot;0. 阅读约定&quot;">​</a></h2><ul><li><strong>【可复现】</strong>：不依赖阿里云产品，你今天在自己的仓库里就能做，并且能量出效果。</li><li><strong>【阿里云主张】</strong>：阿里云团队在书中的判断、内部数据或参考实现，采纳前要按自己的负载复测。</li><li><strong>【外部案例】</strong>：书中引用的公开论文/厂商实践（Anthropic、Qoder Cloud Agent、百炼、RocketMQ LiteTopic 等），属于可借鉴的第三方材料，不是阿里云结论。</li><li><strong>【需按版本核验】</strong>：书中以特定协议版本或产品提交为基线的结论，随版本会变。</li></ul><p>术语约定（全书统一）：<strong>Task</strong> = 异步执行的最小业务单元，有独立标识与业务状态；<strong>Session</strong> = 一段交互/执行上下文；<strong>Task Run</strong> = Task 的一次实际执行；<strong>Artifact</strong> = 可寻址、可交付的成果；<strong>Sandbox</strong> = 按任务分配、有隔离边界的执行环境；<strong>Harness</strong> = 编排层（持有目标、上下文与下一步决策）；<strong>Runtime</strong> = 执行生命周期与资源；<strong>Gateway</strong> = 入口治理点。<strong>Task 与 Session 是业务关联关系，不等于同一进程</strong>（ch10）。</p><hr><h2 id="_1-a-组-任务语义与异步-ch10" tabindex="-1">1. A 组：任务语义与异步（ch10） <a class="header-anchor" href="#_1-a-组-任务语义与异步-ch10" aria-label="Permalink to &quot;1. A 组：任务语义与异步（ch10）&quot;">​</a></h2><h3 id="卡1-把-执行结束-和-业务完成-分成两层" tabindex="-1">卡1 把&quot;执行结束&quot;和&quot;业务完成&quot;分成两层 <a class="header-anchor" href="#卡1-把-执行结束-和-业务完成-分成两层" aria-label="Permalink to &quot;卡1 把&quot;执行结束&quot;和&quot;业务完成&quot;分成两层&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：模型说&quot;完成了&quot;、HTTP 200、流程跑完，被当成业务成功。</li><li><strong>做法</strong>：把一次任务的结论拆成五类信息并分别落库——① 执行状态（running/succeeded/failed/killed）；② 节点运维状态（Worker 是否在线、租约是否有效）；③ 候选证据（日志、Trace、快照、Artifact、LLM 原始响应）；④ Evidence（被成功标准明确引用、可核验来源的证据）；⑤ Outcome（业务应用或获授权 Verifier 依成功标准做出的判定）。运维动作（如&quot;强制标记成功&quot;）只改执行状态并留审计（谁、何时、原因、原状态、新状态）。</li><li><strong>前置条件</strong>：任务有稳定 ID；有可写的状态存储；能区分&quot;人读的材料&quot;和&quot;可判定的证据&quot;。</li><li><strong>适用边界</strong>：任何有验收标准的任务；纯一次性问答可以不建完整五层，但至少要把&quot;执行成功&quot;和&quot;结果被采纳&quot;分开记。</li><li><strong>反例 / 失败模式</strong>：用 LLM 评分直接当业务结论；把 <code>succeeded</code> 直接映射为&quot;客户已收到通知&quot;；审计只留&quot;放行&quot;不留最终执行结果。</li><li><strong>可验证指标</strong>：Outcome 可追溯率（能回溯到 Evidence 的任务 / 全部判定任务）；误判率（人工复核推翻的 Outcome 占比）；审计字段完整率（who/when/reason/from/to 齐全的强制操作占比）。</li><li><strong>一人 / 小团队降级</strong>：一张 <code>runs</code> 表（<code>task_id, status, evidence_url, verified_by, verified_at</code>），人工&quot;验收&quot;只改 <code>verified_*</code> 字段，不改 <code>status</code>。</li><li><strong>原文引用</strong>（ch10）：「LLM-as-a-Judge 是 Evaluation 的一种实现方式，不是 Outcome 的天然权威」「运维侧的&quot;强制标记成功&quot;操作只能在获授权范围内改变执行状态，并留下完整审计记录」「它不能跨越层级直接判定 Outcome」。</li></ul><h3 id="卡2-异步任务-解耦执行生命周期与请求生命周期" tabindex="-1">卡2 异步任务：解耦执行生命周期与请求生命周期 <a class="header-anchor" href="#卡2-异步任务-解耦执行生命周期与请求生命周期" aria-label="Permalink to &quot;卡2 异步任务：解耦执行生命周期与请求生命周期&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：同步请求—响应在长任务上必然超时；进程在等待外部事件期间空占资源。</li><li><strong>做法</strong>： <ol><li>客户端提交任务 → 拿到可靠接收确认与 <strong>Task ID</strong>，请求即返回；</li><li>后台队列按优先级 + FIFO 排序，调度器取任务、租给 Worker、维护租约；</li><li>状态机维护合法转换：<code>waiting → queued → running → succeeded/failed/killed</code>，<code>hold</code> 表示等待审批或外部条件；</li><li>状态持久化到数据库（内存缓存只加速高频查询），数据库是 Task State 的权威源；</li><li>状态通知用&quot;回调为主 + 租约/轮询兜底 + 共享存储做权威持久化&quot;组合。</li></ol></li><li><strong>前置条件</strong>：任务属性显式化（成功标准、重试策略、超时时间、优先级、关联 Session）；有可查询的任务入口。</li><li><strong>适用边界</strong>：超过网关超时、含外部等待或人工介入的任务；几十秒内可完成的调用不要上队列。</li><li><strong>反例 / 失败模式</strong>：把&quot;超时&quot;当作&quot;执行已停止&quot;；把队列深度监控丢掉直到积压才发现；用内存存状态导致进程重启即丢。</li><li><strong>可验证指标</strong>：队列深度与<strong>最老任务等待时长</strong>；端到端完成率；<code>unknown</code> 状态占比（进入对账的比率）。</li><li><strong>一人 / 小团队降级</strong>：<code>cron</code> + SQLite/JSON 状态文件即可实现同样的语义分层；Task ID 用日期 + 序号；&quot;权威源&quot;就是那个文件。</li><li><strong>原文引用</strong>（ch10）：「请求超时只能表示调用方未在期限内取得结果，不能证明执行已经停止」「生产环境通常以数据库为主存储、内存缓存加速高频查询，并把数据库视为 Task State 的权威源」「队列深度本身是核心可观测指标」「背压的本质是让消费速率自适应执行速率，避免过载崩溃」。</li></ul><h3 id="卡3-checkpoint-不等于幂等-把恢复责任写清楚" tabindex="-1">卡3 Checkpoint 不等于幂等：把恢复责任写清楚 <a class="header-anchor" href="#卡3-checkpoint-不等于幂等-把恢复责任写清楚" aria-label="Permalink to &quot;卡3 Checkpoint 不等于幂等：把恢复责任写清楚&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：实例恢复后重复扣款、重复发消息、重复提交。</li><li><strong>做法</strong>： <ol><li>在契约里写清 Checkpoint <strong>保存什么、谁写、与业务状态/外部提交如何排序</strong>；</li><li>区分两件事：<strong>计算结果复用</strong>（Checkpoint 已存在且版本匹配就跳过）与<strong>外部副作用幂等</strong>（另选幂等键、去重账本、事务性 outbox/inbox、租约与 fencing、对账补偿）；</li><li>外部调用可先写&quot;调用意图&quot;，执行后再写&quot;调用结果&quot;，让恢复时能判断是否已提交；</li><li>轮询/回调/Watch 只当<strong>信号</strong>，信号丢失后以权威 Task State 重新对账；</li><li>明确&quot;不能保证恰好一次&quot;时的边界（哪些操作可重放、哪些只能确认或补偿）。</li></ol></li><li><strong>前置条件</strong>：业务操作有稳定唯一键或幂等键；外部系统至少可查询执行结果。</li><li><strong>适用边界</strong>：任何跨进程、跨天的任务；只读分析可以放宽。</li><li><strong>反例 / 失败模式</strong>：把 Checkpoint 当作&quot;事务提交&quot;的替身；靠调度器不重复投递来保证业务不重复；邮件、扣款这类操作试图用恢复检查点&quot;撤销&quot;。</li><li><strong>可验证指标</strong>：恢复后重复副作用条数（应为 0）；对账发现率与对账耗时；恢复后任务续行成功率。</li><li><strong>一人 / 小团队降级</strong>：外部写操作一律带 <code>idempotency_key = hash(task_id + step)</code>；恢复脚本先查&quot;这个 key 写过没有&quot;。</li><li><strong>原文引用</strong>（ch10）：「Checkpoint 必须明确&quot;保存什么、由谁写入、与业务 State 和外部系统提交之间如何排序&quot;，才能参与恢复语义」「轮询、回调、Watch 是状态变化信号，不是权威事实源」「外置调度系统不接管业务 State 权威」「根据交付语义选择幂等机制，不把任何一种写成通用必选项」。</li></ul><h3 id="卡4-定时任务-预授权触发-错过策略-并发上限" tabindex="-1">卡4 定时任务：预授权触发 + 错过策略 + 并发上限 <a class="header-anchor" href="#卡4-定时任务-预授权触发-错过策略-并发上限" aria-label="Permalink to &quot;卡4 定时任务：预授权触发 + 错过策略 + 并发上限&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：定时任务重复跑、漏跑、被工具调用轰炸后无人察觉。</li><li><strong>做法</strong>： <ol><li>触发类型统一成&quot;往队列投递一个 Task&quot;（时间：Cron / ScheduledAt / FixedRate；事件：Webhook / MQ / 内部事件共用同一条执行链路）；</li><li>显式配置：并发上限（1 = 串行）、阻塞处理策略（排队 / 跳过 / 合并为最新一次）、<strong>错过策略</strong>（<code>run_latest</code> 只补最新一次 / <code>run_all</code> 全补跑 / <code>skip</code> 跳过 / <code>prompt</code> 挂起通知人工）、失败重试、超时；</li><li>明确时区与夏令时处理，用<strong>调度 ID + 计划发生时间</strong>标识同一次触发，去重靠这个组合而不是靠时间戳近似；</li><li>无人在场也要算账：预算维度扩到调用次数、执行时长、并发数、外部副作用次数、总费用。</li></ol></li><li><strong>前置条件</strong>：任务有幂等能力（见卡3）；触发与执行路径分离，状态外置。</li><li><strong>适用边界</strong>：日报、周检、周期巡检；秒级高频轮询不要用定时任务，直接用流式/事件。</li><li><strong>反例 / 失败模式</strong>：多实例各自跑定时器导致重复执行（需分布式锁或 Leader 选举）；只写&quot;失败重试 3 次&quot;而不设并发上限；无人值守下死循环 Agent 在数小时内累积出非预期账单。</li><li><strong>可验证指标</strong>：同一次触发的重复执行率；错过触发的补跑决策正确率；单任务日成本与预算告警命中率。</li><li><strong>一人 / 小团队降级</strong>：系统 <code>crontab</code> + 一个 <code>runs</code> 表做触发去重（<code>(trigger_id, planned_at)</code> 唯一索引）；<code>prompt</code> 策略 = 发一条 Telegram/Slack 提醒给自己。</li><li><strong>原文引用</strong>（ch10）：「以调度ID与计划发生时间识别同一次触发」「死循环 Agent 在数小时内累积出非预期账单是真实风险」。</li></ul><h3 id="卡5-人在回路-挂起、重新准入、释放资源" tabindex="-1">卡5 人在回路：挂起、重新准入、释放资源 <a class="header-anchor" href="#卡5-人在回路-挂起、重新准入、释放资源" aria-label="Permalink to &quot;卡5 人在回路：挂起、重新准入、释放资源&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：审批等待期占着 Worker；审批通过后 Agent 用过期状态继续跑；审批回调被当成&quot;必然放行&quot;。</li><li><strong>做法</strong>： <ol><li>任务进入 <code>hold</code> 状态时保存继续点与等待条件，然后<strong>释放执行资源</strong>（前提是恢复所需的最小集合已持久化）；</li><li>审批事件载荷必须带：Task ID、审批版本号、授权主体、决策结论；</li><li>接收方（Runtime 或调度器）据此重新投递前，逐项校验：事件未过期、未重复、与 Task 当前状态兼容；</li><li>等待期仍承担调度、状态存储、通知与可能保留环境的成本，要单独计入成本表；</li><li>审批授权链路由业务应用与 Verifier 定义，流程引擎只负责暂停/恢复协调。</li></ol></li><li><strong>前置条件</strong>：审批请求有唯一 ID 与版本；等待条件可用结构化字段表达。</li><li><strong>适用边界</strong>：高风险写操作、资金动作、外发通知；只读查询不需要。</li><li><strong>反例 / 失败模式</strong>：把&quot;审批通过 → 唤醒 Agent&quot;画成一根没有标注接收方的箭头；超时自动降级为只读执行；恢复时沿用旧心跳/旧凭证直接写入。</li><li><strong>可验证指标</strong>：<code>hold</code> 平均时长与资源占用；审批后重新准入失败的拦截次数；审批事件重复投递被丢弃的比例。</li><li><strong>一人 / 小团队降级</strong>：不用队列，直接&quot;写一个 <code>approvals</code> 表 + 一个后台轮询进程&quot;；Agent 恢复后第一步总是重新读一次 Task 状态再动手。</li><li><strong>原文引用</strong>（ch10）：「把&quot;审批通过 → 回调唤醒 Agent&quot;画成一根没有标注接收方的箭头会掩盖这些必要校验」「Task 与 Session 按业务关联，资源和权限隔离由相应机制保证」。</li></ul><hr><h2 id="_2-b-组-执行环境与沙箱-ch7" tabindex="-1">2. B 组：执行环境与沙箱（ch7） <a class="header-anchor" href="#_2-b-组-执行环境与沙箱-ch7" aria-label="Permalink to &quot;2. B 组：执行环境与沙箱（ch7）&quot;">​</a></h2><h3 id="卡6-会话亲和-工作区挂载-两件独立的事" tabindex="-1">卡6 会话亲和 + 工作区挂载：两件独立的事 <a class="header-anchor" href="#卡6-会话亲和-工作区挂载-两件独立的事" aria-label="Permalink to &quot;卡6 会话亲和 + 工作区挂载：两件独立的事&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：Agent &quot;记不住上次做到哪&quot;，或者工作区被别的实例覆盖。</li><li><strong>做法</strong>： <ol><li><strong>第一类映射</strong>：逻辑会话 → 执行环境（稳定会话标识到达后查已有环境，或启动恢复流程）；</li><li><strong>第二类映射</strong>：任务身份 → 工作区（按已验证的租户/用户/项目关系挂载数据目录）；两者不必一一对应；</li><li>职责切分：源码、下载文件、中间制品在工作区；<strong>任务目标、已完成步骤、待确认事项、外部操作结果属于任务事实，存状态库</strong>；</li><li>恢复后由编排层重新确认进度，不能靠&quot;文件还在&quot;推断任务进度；</li><li>恢复检查未通过时保持&quot;恢复失败/等待&quot;状态，<strong>不把空工作区当恢复成功</strong>；任务状态与工作区的保留期独立于计算实例。</li></ol></li><li><strong>前置条件</strong>：稳定会话标识；工作区归属在服务端校验；任务状态可持久化。</li><li><strong>适用边界</strong>：跨多轮的项目型任务（写代码、数据分析、长文档）；一次性查询不需要。</li><li><strong>反例 / 失败模式</strong>：目录名拼用户 ID 就当访问控制；只因 CPU 低就回收实例而成果只在实例内；把容器临时地址当长期入口。</li><li><strong>可验证指标</strong>：续行成功率（切换实例后从已有成果继续并完成的比例）；工作区挂载失败被正确阻断的比例；状态完整率（恢复后可核对出&quot;已完成步骤&quot;的任务比例）。</li><li><strong>一人 / 小团队降级</strong>：一个持久化项目目录 + <code>SESSION.md</code>（当前目标/进度/待办）随仓库提交；Agent 每次启动先读它。</li><li><strong>原文引用</strong>（ch7）：「仅把用户编号拼接到目录名中，并不能代替服务端对工作区归属及访问权限的检查」「任务目标、已完成步骤、待确认事项和外部操作结果构成任务事实，应由状态存储保存。」「恢复内存和磁盘之后，编排层仍需确认任务进度，避免重复提交操作或遗漏后续步骤」「检查未通过，实例应保持恢复失败或等待状态，不能将空工作区作为恢复结果交付」。</li></ul><h3 id="卡7-等待期成本用-状态分层-而不是-保住进程" tabindex="-1">卡7 等待期成本用&quot;状态分层&quot;，而不是&quot;保住进程&quot; <a class="header-anchor" href="#卡7-等待期成本用-状态分层-而不是-保住进程" aria-label="Permalink to &quot;卡7 等待期成本用&quot;状态分层&quot;，而不是&quot;保住进程&quot;&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：长会话里 Agent 大部分时间在等，按秒计费的实例却一直在跑。</li><li><strong>做法</strong>：按等待时长选状态策略——持续运行 / 浅层暂停（保内存）/ 深度休眠（持久化状态、释放算力，恢复时重建外部连接）/ 只留文件重建进程；并结合<strong>活跃时间占比</strong>、等待时长、恢复频率、状态大小设休眠阈值与保留期限。</li><li><strong>前置条件</strong>：工作区与任务状态已外置（否则无法休眠，见卡6）。</li><li><strong>适用边界</strong>：等待可预测且长的任务（等审批、等外部数据）；高频短等待的反复保存/恢复反而更贵。</li><li><strong>反例 / 失败模式</strong>：以&quot;接口返回成功&quot;判定恢复完成；把某个 pause 接口等同于所有平台的同一种休眠；回收只看 CPU 使用率。</li><li><strong>可验证指标</strong>：<strong>活跃时间占比</strong> = 实际计算时间 ÷（等待 + 计算）；单位完成任务成本；恢复失败率；环境到期回收及时率。</li><li><strong>一人 / 小团队降级</strong>：没有平台就自己在流程里分叉——等待审批时把 Agent 进程 <code>kill</code> 掉，只留状态文件；事件到达后再起新进程读状态。</li><li><strong>原文引用</strong>（ch7）：「仅维持进程存活，无法完整承担这些责任」「接口返回成功只是其中一个环节」「CPU 使用率较低不能单独作为回收依据」。</li></ul><h3 id="卡8-围栏-fencing-让旧执行者真正失效" tabindex="-1">卡8 围栏（Fencing）：让旧执行者真正失效 <a class="header-anchor" href="#卡8-围栏-fencing-让旧执行者真正失效" aria-label="Permalink to &quot;卡8 围栏（Fencing）：让旧执行者真正失效&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：实例 A 失联被判死，新实例 B 接管，A 却复活继续写同一份状态或工作区。</li><li><strong>做法</strong>： <ol><li>区分执行环境故障与依赖服务故障——存储不可用时反复重建实例无用；</li><li>用<strong>执行代次</strong>标识接管前后，写入路径校验代次，旧代次的提交被拒（文件句柄场景用独占挂载或私有分支 + 只允许当前持有者发布新版本）；</li><li>对已提交给外部系统的操作，恢复时按原操作标识查询结果再决定等待/读结果/重试；</li><li>只有任务能从已有成果继续推进，才算恢复完成。</li></ol></li><li><strong>前置条件</strong>：写入入口可控（可校验代次或可做成&quot;发布者&quot;）；外部操作可查询。</li><li><strong>适用边界</strong>：同一任务/工作区存在并发写入者时；纯只读分析可放宽。</li><li><strong>反例 / 失败模式</strong>：只更新任务表里的租约编号；靠心跳判断旧实例已停；快照回滚被误当成撤销外部副作用。</li><li><strong>可验证指标</strong>：旧代次写入被拒次数（应 &gt; 0，说明围栏真的在生效）；并发恢复冲突率；恢复后状态不一致条数。</li><li><strong>一人 / 小团队降级</strong>：本地 Agent 场景用&quot;工作目录互斥锁 + 单写者&quot;；批量导出/发布用&quot;写临时文件 + 原子 rename&quot;。</li><li><strong>原文引用</strong>（ch7）：「失去心跳只表示平台暂时观察不到实例，旧进程仍可能继续运行」「仅更新控制面的编号，不能阻止旧进程继续产生影响」「只有任务能够从已有成果继续推进，才能确认恢复完成」。</li></ul><h3 id="卡9-三类负载分开验收-并用-单位成功任务成本-算账" tabindex="-1">卡9 三类负载分开验收，并用&quot;单位成功任务成本&quot;算账 <a class="header-anchor" href="#卡9-三类负载分开验收-并用-单位成功任务成本-算账" aria-label="Permalink to &quot;卡9 三类负载分开验收，并用&quot;单位成功任务成本&quot;算账&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：&quot;我们上了沙箱/沙箱化，所以有效&quot;。</li><li><strong>做法</strong>：按三类负载分别建基线——① 工具执行（用沙箱：编排在外，按步调用代码/浏览器）；② 长时任务（Agent 在沙箱内：延续项目状态）；③ 训练与评测（批量独立交互、收集轨迹）。每类记录分阶段耗时（排队、分配、镜像准备、挂载、初始化、模型等待、工具运行、验收、释放），P95/P99 必须写明&quot;从哪个事件到哪个事件&quot;；成本用： <strong>单位成功任务成本 =（窗口内归属该负载的计算 + 状态存储 + 网络 + 预热费用）÷ 成功完成的任务数</strong>，失败与重试消耗同样计入。</li><li><strong>前置条件</strong>：有&quot;成功&quot;的客观判据（产物可读、测试通过、指标达标）。</li><li><strong>适用边界</strong>：所有引入执行环境的场景；对比时保持口径一致（含模型调用费）。</li><li><strong>反例 / 失败模式</strong>：用空环境启动耗时代表完整业务响应；把环境故障算进模型能力；评测环境被 Agent 改动后仍用同一份评分材料（需独立保护评分规则与关键验证材料）。</li><li><strong>可验证指标</strong>：完成率、有效反馈率、产物验收通过率、首次可用时延、重复准备耗时、<strong>单位成功任务成本</strong>、有效轨迹吞吐、重置耗时、分支污染率。</li><li><strong>一人 / 小团队降级</strong>：不建平台，只做一件事——为你的 Agent 工作流写一个&quot;完整任务链基线脚本&quot;，每次改动都跑一遍并对比 P50/P95 与&quot;一次成功任务花了多少钱&quot;。</li><li><strong>原文引用</strong>（ch7）：「沙箱快照不能自动回退外部数据库、已经发送的消息或已经完成的业务操作」「对于会修改代码和文件的 Agent，评分规则与关键验证材料应受到独立保护」「高频、稳定的计算可以进一步沉淀为固定工具」「单位成功任务成本」「不能仅依据是否采用沙箱判断收益」。</li></ul><hr><h2 id="_3-c-组-状态、记忆与检索-ch8" tabindex="-1">3. C 组：状态、记忆与检索（ch8） <a class="header-anchor" href="#_3-c-组-状态、记忆与检索-ch8" aria-label="Permalink to &quot;3. C 组：状态、记忆与检索（ch8）&quot;">​</a></h2><h3 id="卡10-运行时状态三件套-event-log-checkpoint-artifact" tabindex="-1">卡10 运行时状态三件套：Event Log / Checkpoint / Artifact <a class="header-anchor" href="#卡10-运行时状态三件套-event-log-checkpoint-artifact" aria-label="Permalink to &quot;卡10 运行时状态三件套：Event Log / Checkpoint / Artifact&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：任务跑了几小时，实例一重启就&quot;失忆&quot;；或者反过来，什么都记下来导致无法判断事实。</li><li><strong>做法</strong>： <ol><li><strong>Event Log（只追加）</strong> 记录任务事实变化；强一致边界放在<strong>任务/会话/业务对象</strong>级，同一任务内有序、独立任务并行；</li><li>事件与当前状态同时维护时用事务或可靠 outbox 保证同步，并按事件 ID 去重；</li><li><strong>Checkpoint</strong> 记录&quot;某个可信时刻的状态&quot;，内容是当前阶段、已完成/未完成步骤、工具结果引用、工作区版本、等待条件、状态版本——不是上下文拷贝；在关键边界（外部调用前后、人工确认前后、工作区重要变更后、交接前）主动打点，并支持增量快照；</li><li><strong>Artifact</strong> 保存可复用成果并给稳定身份 + 元数据（来源任务、版本、生成者、输入依据、审批状态、权限、保留策略）；</li><li>先定义状态对象的正确性边界，再匹配存储能力；别让所有状态落进同一种引擎。</li></ol></li><li><strong>前置条件</strong>：稳定 Task ID；事件/检查点/产物的写入是幂等或可去重的。</li><li><strong>适用边界</strong>：分钟以上的任务；短对话不需要完整三件套。</li><li><strong>反例 / 失败模式</strong>：把诊断日志或模型输出当成可重放事件记录；把所有 Agent 写进同一条全局日志形成串行瓶颈；无限累积事件而不做保留策略。</li><li><strong>可验证指标</strong>：恢复点损失（实例故障后重做的步骤数）；恢复耗时 P95；Evidence→Outcome 可回溯率；产物引用失效数（应为 0）。</li><li><strong>一人 / 小团队降级</strong>：<code>tasks.jsonl</code>（事件追加）+ 每 N 步一个 <code>checkpoints/&lt;ts&gt;.json</code> + <code>artifacts/</code> 目录用内容哈希命名。</li><li><strong>原文引用</strong>（ch8）：「同一任务内部的状态变化需要有明确先后关系，而相互独立的任务可以并发执行」「先定义不同状态对象的正确性边界，再为其匹配相应的存储能力」「实例本地文件可以提供快速读写，却不应成为唯一事实来源」「Agent 需要的不只是容量与吞吐」。</li></ul><h3 id="卡11-分层工作区与不可变产物-区分-试错-和-交付" tabindex="-1">卡11 分层工作区与不可变产物：区分&quot;试错&quot;和&quot;交付&quot; <a class="header-anchor" href="#卡11-分层工作区与不可变产物-区分-试错-和-交付" aria-label="Permalink to &quot;卡11 分层工作区与不可变产物：区分&quot;试错&quot;和&quot;交付&quot;&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：Agent 的临时文件、失败尝试和最终成果混在一起，没人说得清哪个是结论。</li><li><strong>做法</strong>： <ol><li><strong>分层工作区</strong>：底部只读基础层（运行环境、依赖、公共数据）→ 中间共享数据层 → 顶部任务私有可写层；共享不变部分、隔离变化部分；</li><li><strong>Copy-on-Write 快照/分支</strong>：快照给出可回滚的版本边界，并记录&quot;哪个任务、哪个阶段、基于什么输入、由谁生成&quot;；运行时 Checkpoint 记录对应快照引用；</li><li><strong>不可变产物</strong>：进入 Artifact Store 的成果不再原地修改，后续变更生成新版本，引用方永远知道自己读的是哪一份；</li><li>保留策略分层：一次性中间文件按策略清理，正式成果按业务/合规周期保存。</li></ol></li><li><strong>前置条件</strong>：工作区可挂载、有私有可写层；产物有稳定引用方式。</li><li><strong>适用边界</strong>：会产生文件与数据集的任务（分析、代码、报告）；纯问答不需要。</li><li><strong>反例 / 失败模式</strong>：把实例本地目录当唯一事实来源；用&quot;环境回滚&quot;撤销已提交到外部系统的操作；多个 Agent 直接改同一目录，退化成不可审计的文件覆盖竞争。</li><li><strong>可验证指标</strong>：产物引用可解析率；回滚正确率；临时文件清理及时率；跨 Agent 合并冲突率。</li><li><strong>一人 / 小团队降级</strong>：Git 就是你的快照与分支；把&quot;交付物&quot;放到单独 <code>deliverables/</code> 目录，文件名带日期与内容哈希。</li><li><strong>原文引用</strong>（ch8）：「环境回滚不撤销已经提交到外部系统的操作」「一次性中间文件可以在任务结束后按策略清理」。</li></ul><h3 id="卡12-记忆写入管线-只记经过验证的-并允许遗忘" tabindex="-1">卡12 记忆写入管线：只记经过验证的，并允许遗忘 <a class="header-anchor" href="#卡12-记忆写入管线-只记经过验证的-并允许遗忘" aria-label="Permalink to &quot;卡12 记忆写入管线：只记经过验证的，并允许遗忘&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：Agent 把猜测当事实，越用越自信；旧偏好一直污染新回答；用户要求删除却删不干净。</li><li><strong>做法</strong>： <ol><li><strong>抽取</strong>：只抽取对后续交互有预测价值的信息；寒暄、临时调试指令、一次性查询不入长期记忆；</li><li><strong>合并与冲突消解</strong>：与已有记忆做语义匹配、去重、覆盖或标记&quot;待确认&quot;；保留来源与边界（谁产生、经过什么验证、适用哪个场景、何时写入、是否仍有效）；</li><li><strong>检索</strong>：语义 + 关键词 + 实体关系多路召回后统一排序；时间衰减只作加权，<strong>不能用来淡出长期有效的约束</strong>；</li><li><strong>遗忘</strong>：归档 / 降召回权重 / 删除是三种不同操作；删除要同步处理原始记录、摘要、索引与缓存，并防止后续重建把它重新引入；无法确定的概括保留&quot;待确认&quot;状态而不是硬写；</li><li>人设与身份配置（Persona）由构建方显式维护，不来自 Agent 经历。</li></ol></li><li><strong>前置条件</strong>：记忆条目有来源字段与写入时间；能区分原始记录与摘要/索引副本。</li><li><strong>适用边界</strong>：有跨会话复用的产品；一次性任务不需要记忆系统。</li><li><strong>反例 / 失败模式</strong>：把对话历史整段存进向量库当记忆（&quot;共用一个向量数据库&quot;不等于团队记忆）；用引用频率当正确性证据；只删主记录、索引里还在。</li><li><strong>可验证指标</strong>：记忆陈旧引用率（后续任务引用了已被更正记忆的比例）；删除生效时延（请求删除 → 索引与缓存清理完成）；记忆命中率与误命中（命中但不该命中）比例。</li><li><strong>一人 / 小团队降级</strong>：一个 <code>MEMORY.md</code>（带&quot;最后确认时间&quot;和&quot;来源&quot;两列）+ 每月人工复核一次；删除就是直接删行 + 重建索引。</li><li><strong>原文引用</strong>（ch8 / ch11）：「记忆不是原始对话的简单归档，而是经过结构化加工后的认知沉淀」「未经验证的内容如果直接进入长期记忆，容易在后续任务中被当作事实反复引用」「归档、降低召回权重与删除是不同操作」「用户要求删除的信息需要同步处理原始记录、摘要、索引和缓存」「时间衰减可以提高近期记忆的排序权重，但不适用于所有信息」。</li></ul><h3 id="卡13-检索前过滤权限-并区分权威事实与派生视图" tabindex="-1">卡13 检索前过滤权限，并区分权威事实与派生视图 <a class="header-anchor" href="#卡13-检索前过滤权限-并区分权威事实与派生视图" aria-label="Permalink to &quot;卡13 检索前过滤权限，并区分权威事实与派生视图&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：向量检索跨租户召回后再过滤，泄漏发生在&quot;候选生成&quot;阶段；索引与主数据不一致导致结论陈旧。</li><li><strong>做法</strong>： <ol><li>权限过滤前置到<strong>索引空间、检索条件与重排序策略</strong>，让 Agent 只在被授权的语义空间里召回；覆盖检索到生成的全链路，避免推理成为旁路；</li><li>一致性分级：影响任务正确性的运行时状态（租约、工具调用结果、关键检查点）以强一致/可验证提交为目标；向量索引、全文检索、统计聚合接受短暂最终一致，但要能说出新鲜度与对应源数据版本；</li><li>写入顺序：先可靠提交权威事实，再异步或增量推动索引与副本；查询流量切换到新索引前必须达到可用水位；</li><li>回答要能标注引用的对象版本、索引时间与来源，让&quot;过期&quot;能被定位到数据还是模型；</li><li>交互只能提出候选事实或模型修订建议，<strong>不得把模型推测直接写成组织规则</strong>。</li></ol></li><li><strong>前置条件</strong>：租户/权限标识能进入索引与查询参数；索引与主数据之间有水位或版本号。</li><li><strong>适用边界</strong>：多租户或含敏感语料的知识/记忆检索；单用户本地库可简化。</li><li><strong>反例 / 失败模式</strong>：先跨租户召回再在应用层过滤；把索引当权威事实；用回滚掩盖脏数据。</li><li><strong>可验证指标</strong>：越权召回条数（应为 0）；索引滞后 P95；结论可溯源率（回答能定位到文档段落与版本的比例）。</li><li><strong>一人 / 小团队降级</strong>：检索前先用目录/命名空间隔离（例如每个客户一个 collection 或一个 <code>docs/&lt;client&gt;/</code> 前缀过滤），不要靠回答后过滤。</li><li><strong>原文引用</strong>（ch8）：「语义检索若先跨租户召回、再过滤结果，可能已在候选生成阶段引入不必要的数据暴露风险」「不得将模型推测直接写成组织规则」「故障恢复同样遵循这一分工：控制平面定义恢复策略，执行平面的 Runtime 负责落实」。</li></ul><hr><h2 id="_4-d-组-通信语义与-multi-agent-协作-ch12-ch11" tabindex="-1">4. D 组：通信语义与 Multi-Agent 协作（ch12 / ch11） <a class="header-anchor" href="#_4-d-组-通信语义与-multi-agent-协作-ch12-ch11" aria-label="Permalink to &quot;4. D 组：通信语义与 Multi-Agent 协作（ch12 / ch11）&quot;">​</a></h2><h3 id="卡14-通信语义四档-选-最低充分-并写出六要素契约" tabindex="-1">卡14 通信语义四档：选&quot;最低充分&quot;，并写出六要素契约 <a class="header-anchor" href="#卡14-通信语义四档-选-最低充分-并写出六要素契约" aria-label="Permalink to &quot;卡14 通信语义四档：选&quot;最低充分&quot;，并写出六要素契约&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：一律用长连接/同步调用，长任务撑不住；或者一律上消息队列，简单调用复杂化。</li><li><strong>做法</strong>：把通信面分为<strong>人机面、能力面、协作面、内构面</strong>，交互语义分四档： S1 请求—响应 / S2 请求域流式 / S3 任务句柄（提交后凭 ID 查询或订阅）/ S4 持久通道（订阅、确认、补读）。 逐段检查&quot;这段通信需要独立任务句柄吗？需要补读事件吗？&quot;再选档；默认从最低充分档开始，只在实际需要的链路加机制。每段通信的契约写清六个要素：<strong>标识、顺序、投递保证（至少一次/至多一次/恰好一次 + 去重键）、续传点、生命周期、背压</strong>。</li><li><strong>前置条件</strong>：会话与任务有独立标识（连接只是当前传输路径）；结果查询与续传分别声明。</li><li><strong>适用边界</strong>：全部 AI 原生应用通信；短调用用 S1，人机交互用 S2，Agent 交接用 S3，削峰与补读才上 S4。</li><li><strong>反例 / 失败模式</strong>：把流式结束当作任务结束；有任务句柄就以为有事件重播；把推送通知当成结果送达（它是&quot;去拉取&quot;的触发器）；把协议无状态理解成业务无状态；把&quot;会话 = 常驻进程&quot;绑死导致扩容迁移困难。</li><li><strong>可验证指标</strong>：断连后可恢复率（重连后能补齐遗漏事件/查到任务状态的比例）；长任务查询成功率；投递重复率与幂等丢弃率；积压深度。</li><li><strong>一人 / 小团队降级</strong>：两档就够——短调用同步，长任务&quot;提交 + 轮询一个 URL&quot;。补上 <code>task_id</code>、状态查询接口、幂等键三样，其余不必上。</li><li><strong>原文引用</strong>（ch12）：「选型的起点是为每个通信面选择成本与风险可接受的最低充分语义，而不是统一采用最高档位」「会话与任务应有独立标识，连接只是当前的数据传输路径」「有任务句柄不一定有完整事件重播，有事件序号也不自动保证业务状态可恢复」「推送通知的角色是&quot;去拉取&quot;的触发器，结果的可寻址性仍由任务查询保证」「协议无状态不等于应用无状态」「不能将无状态核心解释为没有持续通知连接」「任务状态、检查点、消息日志和消费位置各有职责」「需要逐段检查调用时限、结果获取和恢复要求，再选择合适的通信方式」。</li></ul><h3 id="卡15-通道键决定治理粒度-决策与执行分离-手脑分离" tabindex="-1">卡15 通道键决定治理粒度；决策与执行分离（手脑分离） <a class="header-anchor" href="#卡15-通道键决定治理粒度-决策与执行分离-手脑分离" aria-label="Permalink to &quot;卡15 通道键决定治理粒度；决策与执行分离（手脑分离）&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：一个共享队列下，某客户/某会话的突发拖垮所有人；执行环境成了不能替换的&quot;宠物&quot;。</li><li><strong>做法</strong>： <ol><li><strong>通道键选在业务并发单元上</strong>（会话标识、用户、用户×模型组合），让通道天然成为隔离、限流、观测与回收的粒度；</li><li><strong>手脑分离</strong>：Harness（决策）无状态，凭会话标识唤醒、拉取事件历史续跑；沙箱降级为&quot;一只普通的工具&quot;，失败表现为工具层错误而不是会话中断；会话是追加式事件日志，不等于模型上下文窗口；</li><li>反模式：会话与常驻工作进程一对一绑死（持续占用算力、断线丢上下文、扩容迁移困难）。</li></ol></li><li><strong>前置条件</strong>：会话状态外置且可重放；执行侧可按需申请/释放（见卡6、卡7）。</li><li><strong>适用边界</strong>：多会话、多执行环境的中等以上规模系统；单机单会话不必。</li><li><strong>反例 / 失败模式</strong>：用共享队列做隔离却额外补一套路由表；把某个容器地址当长期入口；以为&quot;进程还活着 = 任务还在跑&quot;。</li><li><strong>可验证指标</strong>：单通道积压隔离成功率（一个通道堆积不影响其他）；会话恢复成功率；会话状态占用的单位成本；换机后任务续行成功率。</li><li><strong>一人 / 小团队降级</strong>：按&quot;项目/客户&quot;分目录 + 分队列（或至少分限流键），不要一个全局队列；执行侧保持&quot;随时可重启&quot;，状态在文件里。</li><li><strong>原文引用</strong>（ch12）：「通道以什么业务标识命名，就决定了隔离、限流、观测与回收以什么粒度进行」「把通道键选在业务并发单元上，让通道天然成为治理单元」「会话不等于模型的上下文窗口」「任务不属于某台机器，机器只负责当前这一棒」「将会话与常驻工作进程一对一绑死」。**【外部案例】**书中把该结构归到 Anthropic 的&quot;meta-harness&quot;与 Qoder Cloud Agent 的四层手脑分离（Agent Runtime / MQ / Sandbox Worker / Session State），并用 RocketMQ LiteTopic 承载海量的 Session-as-Topic；引用其结论时要注明是第三方材料。</li></ul><h3 id="卡16-multi-agent-上线判据-收益必须覆盖协调成本" tabindex="-1">卡16 Multi-Agent 上线判据：收益必须覆盖协调成本 <a class="header-anchor" href="#卡16-multi-agent-上线判据-收益必须覆盖协调成本" aria-label="Permalink to &quot;卡16 Multi-Agent 上线判据：收益必须覆盖协调成本&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：为了&quot;多 Agent&quot;而多 Agent——所有信息汇到一个主管，反而回到单点瓶颈。</li><li><strong>做法</strong>： <ol><li>先判断任务是否<strong>真的</strong>有专业分工、独立权限、可并行交付、故障隔离需求；否则用单 Agent；</li><li>组织拓扑三选一（主管—执行 / 对等协作 / 分层编排），并写明谁决定什么、何时寻求协调；</li><li>明确判断标准：只有当分工、并行、隔离与治理收益覆盖沟通与协调成本时才值得；</li><li>避免&quot;主管替执行者解决专业问题 + 执行者等主管决定每一步&quot;的双向低效；</li><li>验收口径是<strong>成员分工与共同交付是否成立</strong>，而不是&quot;有几个 Agent&quot;。</li></ol></li><li><strong>前置条件</strong>：每个成员有清晰的能力边界与责任归属；共享事实落在 Task State / Artifact（见卡17）。</li><li><strong>适用边界</strong>：需求分析 + 实现 + 测试 + 安全 + 上线审批这类跨专业链路；单一目标的短任务不要上。</li><li><strong>反例 / 失败模式</strong>：主管 Agent 成为上下文与执行瓶颈；角色只停留在名称上；Agent 交接被当成权限扩大；子代理未显式授权就当作团队成员。</li><li><strong>可验证指标</strong>：协调开销比（协调消息数 ÷ 有效执行步骤数）；任务端到端时长 vs 单 Agent 基线；返工轮次；成员阻塞时长。</li><li><strong>一人 / 小团队降级</strong>：&quot;一人公司&quot;其实是单成员团队——保持单 Agent，把子任务做成 Task Run 而不是新 Agent；只有在<strong>并行</strong>真的省时间时才开第二个进程。</li><li><strong>原文引用</strong>（ch11）：「如果所有信息都必须先汇总到一个主管 Agent，再由它决定每一个步骤，多智能体系统很容易重新回到单点决策的模式，主管 Agent 也会成为新的上下文和执行瓶颈」「只有当专业分工、并行执行、故障隔离和过程治理带来的收益，能够覆盖沟通与协调成本时，Agent 团队才真正具有价值」「团队编排需要验证的，是成员分工与共同交付是否成立」。</li></ul><h3 id="卡17-最小充分共享-task-级停止条件" tabindex="-1">卡17 最小充分共享 + Task 级停止条件 <a class="header-anchor" href="#卡17-最小充分共享-task-级停止条件" aria-label="Permalink to &quot;卡17 最小充分共享 + Task 级停止条件&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：共享不足导致重复探索与状态冲突；共享过量把噪声与错误扩散给所有人；任务无限重试烧钱。</li><li><strong>做法</strong>： <ol><li><strong>共享的是上下文来源，不是同一个 Context 窗口</strong>：目标、约束、任务状态、已确认事实与产物构成来源，每个 Agent 按角色/任务/权限/阶段取自己需要的视图；</li><li><strong>Handoff 四类信息</strong>：目标（范围与交付要求）、已知事实（已确认信息与已完成工作）、待处理事项（未解决问题、依赖与关键约束）、可用引用（可继续使用的 Task / 数据 / Artifact 引用）；完整搜索过程与未验证的中间推理通常不传递；</li><li><strong>事实载体分工</strong>：消息说&quot;发生了什么&quot;，Task State 与 Artifact 记录&quot;当前事实是什么&quot;；接收方通过可访问的 Artifact 引用取成果，而不是消息摘要或本地绝对路径；</li><li><strong>停止条件在根 Task 开始前约定</strong>：总时间/成本预算、最大委派深度、派生任务数、单项重试次数、返工轮次，以及&quot;连续多轮无新增有效产物&quot;时的处理；触顶后暂停新委派、保留已完成结果与剩余预算，交人工判断；单个 Agent 的重试上限不能替代这一级约束；</li><li>已有材料足以证明结果时，不为形式完整重复制作报告。</li></ol></li><li><strong>前置条件</strong>：Task / Task Run / Session 三者分别标识并按需关联；成员能读到产物引用。</li><li><strong>适用边界</strong>：多成员协作与长程任务；单人工作流适用其&quot;停止条件&quot;部分。</li><li><strong>反例 / 失败模式</strong>：把对话历史当 Team State；消息发送成功就认为任务被承接；一次性把全部上下文广播给所有成员；无人值守下自动返工无限循环。</li><li><strong>可验证指标</strong>：重复劳动率（同任务内重复执行已确认步骤的比例）；交接后可继续率；停止条件触发次数与触发后人工介入时长；派生任务数/根任务数。</li><li><strong>一人 / 小团队降级</strong>：给自己写一份&quot;任务契约&quot;：目标、交付物、预算上限（次数/时长/金额）、停止条件；写在任务文件头部，每次启动先读它。</li><li><strong>原文引用</strong>（ch11）：「团队共享的是 上下文来源，而不是完全相同的 Context」「成员可以通知一份报告已经生成，但接收方应通过可访问的 Artifact 引用取得报告本身」「本地 Agent 生成报告后，如果只回复一个绝对路径，其他机器上的成员通常无法读取」「团队级停止条件需要在根 Task 开始前约定」「消息可以触发任务或补充信息，但发送成功不代表任务已经被承接。」「一次消息可以触发协作，却不能单独代表工作已经被承接或完成」「已有材料能够证明结果时，也不必为了形式完整重复制作报告」。</li></ul><hr><h2 id="_5-e-组-网关与流量治理-ch9" tabindex="-1">5. E 组：网关与流量治理（ch9） <a class="header-anchor" href="#_5-e-组-网关与流量治理-ch9" aria-label="Permalink to &quot;5. E 组：网关与流量治理（ch9）&quot;">​</a></h2><h3 id="卡18-严格预算-阈值检查" tabindex="-1">卡18 严格预算 ≠ 阈值检查 <a class="header-anchor" href="#卡18-严格预算-阈值检查" aria-label="Permalink to &quot;卡18 严格预算 ≠ 阈值检查&quot;">​</a></h3><ul><li><p><strong>要解决的问题</strong>：以为&quot;请求前查余额、响应后扣减&quot;就能卡住花费；并发下直接超支。</p></li><li><p><strong>做法</strong>：区分四种机制并各自承诺边界——请求速率限制（QPS/令牌桶）、token 时间窗限制（请求前检查、结束后累计）、余额型配额（准入查余额、结束扣减）、<strong>严格预算</strong>（可证明的最大消耗 + 准入时原子预留 + 幂等结算 + 退款）。严格预算的不变量：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>可用额度 = 已授权额度 − 已结算消耗 − 在途预留</span></span>
<span class="line"><span>准入条件 = 本次最大可计费消耗 ≤ 可用额度</span></span></code></pre></div><p>预留要覆盖输入、受约束的最大输出与其他计费项，<strong>每次重试单独占用额度</strong>；流式中断或结果未知的请求不能因租约到期就无条件退款；token 配额与金额预算分开建模。</p></li><li><p><strong>前置条件</strong>：调用能拿到可验证的最大消耗；预留与结算是同一原子操作或等效一致性事务。</p></li><li><p><strong>适用边界</strong>：多团队/多项目的无人值守 Agent；个人单用户可只做速率限制 + 日预算告警。</p></li><li><p><strong>反例 / 失败模式</strong>：把阈值插件当严格上限宣称；把缺失 usage 记为零消耗；用 credits 当统一货币；只在某一层预留导致悬挂记录。</p></li><li><p><strong>可验证指标</strong>：预算超限率（实际消耗/授权额度 &gt; 1 的窗口占比）；未结算用量占比与对账差异；重试造成的额度占用占比。</p></li><li><p><strong>一人 / 小团队降级</strong>：模型调用加&quot;每日 token 上限 + 超限自动降级到小模型/暂停&quot;，用供应商账单或自建 usage 表对账；达不到原子预留就如实声明&quot;软预算&quot;。</p></li><li><p><strong>原文引用</strong>（ch9）：「两次最大消耗分别为 80 的请求同时通过余额检查，最终消耗就可能达到 160」「响应后的原子扣减可以避免丢账，但不能撤销已经发生的消耗」「可用额度 = 已授权额度 − 已结算消耗 − 在途预留」「区分时间窗限制、余额配额和严格预算」「若现有插件仅支持阈值控制，就如实声明边界」「缺少 usage 不能记录为零消耗，客户端取消也不能证明上游停止生成」「缓存键还必须区分租户、权限范围、模型版本、系统提示和知识版本」。</p></li></ul><h3 id="卡19-重试预算跨层传递-别让-3×3-9" tabindex="-1">卡19 重试预算跨层传递：别让 3×3=9 <a class="header-anchor" href="#卡19-重试预算跨层传递-别让-3×3-9" aria-label="Permalink to &quot;卡19 重试预算跨层传递：别让 3×3=9&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：客户端重试 3 次、网关重试 3 次，一次用户调用打到上游 9 次；故障被多层恢复机制放大且无法归因。</li><li><strong>做法</strong>： <ol><li>先判断<strong>能否重试</strong>，再选重试目标：限流看重置时间与配额，服务端错误只在调用语义允许时重试，认证错误直接终止并修凭证，上下文超限交给应用/Harness 决定而不是截断历史；</li><li>尝试预算<strong>跨层传递</strong>：总截止时间是绝对时间，网关只保留必要的传输余量；剩余尝试额度由调用方给出，网关按 <code>call_id</code> 原子扣减，耗尽返回明确错误；</li><li>每次实际尝试用稳定的 <code>call_id</code> + <code>attempt_id</code> 关联，重试、摘除、模型切换分开记录；</li><li>切换 provider 前检查工具、结构化输出、数据地域与模型能力兼容性；没有验证过的兜底路径返回可解释失败。</li></ol></li><li><strong>前置条件</strong>：调用有业务幂等键或能确认尚未提交执行；有跨层传递的截止时间与额度。</li><li><strong>适用边界</strong>：所有有重试的调用链（SDK → 网关 → 上游）；不重试的路径也建议记录 attempt。</li><li><strong>反例 / 失败模式</strong>：按 HTTP 状态或&quot;是否收到首包&quot;决定重试（请求可能已计费或已触发副作用）；流式响应向客户端提交后还想透明重放；真实探活产生费用并被多副本放大。</li><li><strong>可验证指标</strong>：<strong>重试放大系数</strong> = 上游实际尝试次数 ÷ 逻辑调用次数；未知结果率；每逻辑调用的成本分布 P95。</li><li><strong>一人 / 小团队降级</strong>：在 SDK 层做唯一重试点，网关/代理层重试关闭；用 <code>idempotency_key</code> + 总超时兜底。</li><li><strong>原文引用</strong>（ch9）：「如果 SDK 客户端对一次逻辑调用最多尝试 3 次，网关对每次转发又最多重试 3 次，那么一次用户可见的调用最多会到达上游 9 次」。</li></ul><h3 id="卡20-工具授权-默认拒绝、审批后重新准入" tabindex="-1">卡20 工具授权：默认拒绝、审批后重新准入 <a class="header-anchor" href="#卡20-工具授权-默认拒绝、审批后重新准入" aria-label="Permalink to &quot;卡20 工具授权：默认拒绝、审批后重新准入&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：模型能&quot;看见&quot;就能&quot;调&quot;；审批过了就直接执行；超时把高风险操作悄悄降级成只读。</li><li><strong>做法</strong>： <ol><li><strong>协议说明不是身份证明</strong>：认证（独立凭据的主体映射）→ 协议校验 → 授权（主体/工具/参数）→ 转发，四步分开；逐请求元数据只服务于协议校验与转发；</li><li><strong>默认拒绝</strong>：工具权限取调用者原有授权、工作负载授权、任务委托范围与资源侧限制的交集；过滤工具列表只是减少误选，<strong>调用时必须再次鉴权</strong>；输入 Schema 校验只保证结构合规，不证明业务授权；</li><li><strong>审批未决的请求不得转为实际执行</strong>；批准后要<strong>重新准入</strong>（身份、委托、参数摘要、预算预留），因为等待期间这些都可能过期；审批记录含调用者、工具及版本、参数摘要、风险与有效期，回调需认证与防重放；</li><li>超时不自动降级为只读执行；无幂等支持的外部操作在结果不明时交给业务查询或补偿；</li><li>入口要&quot;不可绕过&quot;才有资格当策略执行点：凭证不下发、出口网络受控、直连路径禁止且旁路受审计；否则它只是集中入口。</li></ol></li><li><strong>前置条件</strong>：主体与凭证分离；工具调用有统一入口；策略有版本与命中记录。</li><li><strong>适用边界</strong>：多 Harness、多团队共享工具的平台；工具少时可在框架内做同等检查。</li><li><strong>反例 / 失败模式</strong>：用模型自述身份或 <code>clientInfo</code> 扩大权限；REST-to-MCP 模板放开可变主机/路径造成 SSRF；只靠&quot;只读 SQL 前缀判断&quot;判断写操作；日志记录带密钥的地址与请求头。</li><li><strong>可验证指标</strong>：策略拒绝率与拒绝原因可解释率；审批后重新准入被拦截次数；绕行直连次数（应为 0）；高风险工具未授权调用数（应为 0）。</li><li><strong>一人 / 小团队降级</strong>：不做网关，做&quot;工具白名单 + 参数 Schema 校验 + 危险操作二次确认（人工粘贴确认码）&quot;；密钥放环境变量、绝不进 prompt。</li><li><strong>原文引用</strong>（ch9）：「协议说明不是调用者身份证明」「过滤 <code>tools/list</code> 可以减少模型误选无权工具，但 <code>tools/call</code> 仍必须再次鉴权」「权限应取调用者原有授权、工作负载授权、任务委托范围和资源侧限制的交集」「审批未决的请求不得转为实际执行」「对于无幂等支持的外部操作，超时后的执行结果不确定必须交由业务查询或补偿流程处理，不能由网关盲目重试」「客户端看到同一个模型名，不应意味着平台可以不经验证地替换其实际能力」。</li></ul><h3 id="卡21-成本与结果归因-从-session-扩展到-task-分层账本" tabindex="-1">卡21 成本与结果归因：从 Session 扩展到 Task 分层账本 <a class="header-anchor" href="#卡21-成本与结果归因-从-session-扩展到-task-分层账本" aria-label="Permalink to &quot;卡21 成本与结果归因：从 Session 扩展到 Task 分层账本&quot;">​</a></h3><ul><li><strong>要解决的问题</strong>：知道&quot;这轮对话花了多少&quot;，回答不了&quot;这项长任务花了多少、恢复了几次、结果如何&quot;；把网关 200 当业务成功。</li><li><strong>做法</strong>：建立归因链路 <code>task_id → session_id → turn_id → model/tool call → attempt_id</code>；<code>task_id</code> 来自业务应用，网关只生成请求/尝试标识；客户端带来的关联头要绑定已认证主体并校验租户范围，防伪造转移费用。分层记录：Attempt（端点、计费模型、用量来源、状态、错误、耗时）/ Call·Turn（多次尝试、上下文变化）/ Session（累计用量、等待与失败分布）/ Task（跨会话归集、恢复阶段、运行资源费用、Outcome 引用）。<strong>网关请求成功率与业务任务完成率分别统计</strong>；缺少 Outcome 或未结算成本的任务保留对应状态。</li><li><strong>前置条件</strong>：可信身份与稳定的任务标识；记录含身份引用、任务/会话/轮次关联、实际模型、用量来源、状态、时延与策略版本。</li><li><strong>适用边界</strong>：长程任务、需要 FinOps 的团队；短会话可只做 Call/Session 两层。</li><li><strong>反例 / 失败模式</strong>：把一条 Trace 或 Session 当完整 Task 账本；把网关记录冒充完整任务账本；用高基数字段（task_id、session_id）做指标标签拖垮监控；内容字段无差别全量落日志。</li><li><strong>可验证指标</strong>：<strong>成本归因完整率</strong> = 可归因到 <code>task_id</code> 的费用 ÷ 总费用；Outcome 回填率；未结算用量占比；单位任务成本（按任务类型分）。</li><li><strong>一人 / 小团队降级</strong>：每次 Agent 运行写一条 <code>usage.json</code>（时间、任务名、模型、输入/输出 token、耗时、结果状态），月底用一条 SQL 汇总到&quot;每个任务多少钱&quot;。</li><li><strong>原文引用</strong>（ch9）：「网关记录是调用账本的一部分，不应冒充完整任务账本」「网关的请求成功率与业务任务完成率分别统计」「网关只保证准入、转发与记录的一致性，既不能仅凭请求成功断言任务完成」「Evaluation 不天然拥有发布授权」「不能因为网关是多副本，就认为其依赖已经没有单点」。</li></ul><hr><h2 id="_6-主张分类-阿里云判断-内部数据-vs-你可以自己复现的做法" tabindex="-1">6. 主张分类：阿里云判断/内部数据 vs 你可以自己复现的做法 <a class="header-anchor" href="#_6-主张分类-阿里云判断-内部数据-vs-你可以自己复现的做法" aria-label="Permalink to &quot;6. 主张分类：阿里云判断/内部数据 vs 你可以自己复现的做法&quot;">​</a></h2><p><strong>A. 阿里云团队主张与内部数据（采纳前按自身负载复测）</strong></p><table tabindex="0"><thead><tr><th>内容</th><th>出处</th><th>性质</th></tr></thead><tbody><tr><td>Task/State/Harness/Runtime/调度器 的责任划分与&quot;完成语义五层&quot;</td><td>ch10</td><td>团队主张（框架性判断）</td></tr><tr><td>沙箱三类负载与状态分层表、验证方式</td><td>ch7</td><td>团队主张 + 产品实践提炼</td></tr><tr><td>Lakebase 参考架构（运行状态、工作区、记忆、知识、本体统一对象模型）与&quot;对轻量场景组件组合仍是合理起点&quot;</td><td>ch8</td><td>产品架构主张</td></tr><tr><td>Higress <code>ai-token-ratelimit</code> / <code>ai-quota</code> 的实现范围与 Redis 故障分支不一致</td><td>ch9</td><td>版本敏感的实现结论（书中以特定提交为基线）</td></tr><tr><td>百炼网关漏桶外置、&quot;用户×模型&quot;通道限流；资产中心&quot;用户&quot;通道键</td><td>ch9 / ch12</td><td>内部案例与做法</td></tr><tr><td>Qwen、百炼、Z.ai、MiniMax 的沙箱与训练评测案例的性能/成本结果</td><td>ch7</td><td>产品案例数据（书中已声明条件相关）</td></tr></tbody></table><p><strong>B. 【需按版本核验】的协议与生态事实</strong>（书中给出的版本/日期，请以官方规范为准再引用）</p><p>MCP 2026-07-28 的逐请求元数据与 Tasks 扩展转正、A2A v1.0.0、ACP v2 仍为 Draft、Envoy AI Gateway 更名 Agent Router 且 v1.0.0 于 2026-06-23 GA、Gateway API Inference Extension 的 <code>InferencePool</code> v1、Apache Airflow 3.1.0 引入 HITL、MCP 2025-11-25 实验性 Tasks —— ch9 / ch10 / ch12。</p><p><strong>C. 【外部案例】第三方材料</strong></p><p>Anthropic 的&quot;把大脑与双手解耦&quot;与 meta-harness、Claude Code Remote Control、Qoder Cloud Agent 四层手脑分离（Agent Runtime / RocketMQ / Sandbox Worker / Session State）、RocketMQ LiteTopic、RocketMQ-A2A 的 FSE 2026 论文、HiRoute、OpenRouter/LiteLLM/Portkey 生态比较 —— ch9 / ch12。</p><p><strong>D. 【可复现】不依赖上述产品、今天就能做并能量化的做法</strong></p><ol><li>完成语义分层与 Outcome 判定权归属（卡1）</li><li>异步任务状态机 + 权威状态存储 + 队列深度指标（卡2）</li><li>Checkpoint 与副作用幂等的责任划分、对账（卡3）</li><li>定时任务的并发上限与错过策略、触发去重（卡4）</li><li>审批挂起与&quot;重新准入&quot;校验（卡5、卡20）</li><li>工作区归属服务端校验 + 恢复后进度复核（卡6）</li><li>状态分层降低等待成本（卡7）</li><li>围栏让旧执行者失效（卡8）</li><li>三类负载基线与&quot;单位成功任务成本&quot;（卡9）</li><li>Event Log / Checkpoint / Artifact 三件套与分层工作区（卡10、卡11）</li><li>记忆抽取—合并—遗忘管线（卡12）</li><li>检索前权限过滤 + 权威事实/派生视图分层（卡13）</li><li>通信四档语义与六要素契约、通道键治理粒度（卡14、卡15）</li><li>Multi-Agent 收益判据、最小充分共享、Task 级停止条件（卡16、卡17）</li><li>严格预算不变量与重试预算跨层传递（卡18、卡19）</li><li>工具默认拒绝与 Task 分层成本账本（卡20、卡21）</li></ol><hr><h2 id="_7-一人公司-小团队降级路线" tabindex="-1">7. 一人公司 / 小团队降级路线 <a class="header-anchor" href="#_7-一人公司-小团队降级路线" aria-label="Permalink to &quot;7. 一人公司 / 小团队降级路线&quot;">​</a></h2><p>原则：保留<strong>语义分层与判定权</strong>，砍掉平台与中间件。</p><table tabindex="0"><thead><tr><th>卡</th><th>完整做法</th><th>降级做法（1 人 / 2—5 人）</th></tr></thead><tbody><tr><td>卡1</td><td>五层完成语义 + Verifier</td><td><code>runs</code> 表两列：<code>status</code>（执行）与 <code>verified</code>（业务采纳），人工只改后者</td></tr><tr><td>卡2</td><td>队列 + 调度器 + 租约 + 数据库权威</td><td><code>cron</code>/GitHub Actions + SQLite 状态文件；Task ID = <code>YYYYMMDD-nn</code></td></tr><tr><td>卡3</td><td>幂等键 / outbox / fencing / 对账</td><td>所有外部写带 <code>idempotency_key</code>；恢复脚本先查 key</td></tr><tr><td>卡4</td><td>集中调度 + 错过策略</td><td>系统 crontab + <code>(trigger_id, planned_at)</code> 唯一索引；错过 = 下次补跑一次并记录</td></tr><tr><td>卡5</td><td><code>hold</code> 状态 + 审批事件校验</td><td>一个 <code>approvals</code> 表 + 轮询；恢复后第一步重读 Task 状态</td></tr><tr><td>卡6</td><td>会话亲和 + 工作区挂载</td><td>持久化项目目录 + <code>SESSION.md</code>（目标/进度/待办），每次启动先读</td></tr><tr><td>卡7</td><td>浅/深休眠与资源分层</td><td>等待时直接结束 Agent 进程，只留状态文件；事件到达再起</td></tr><tr><td>卡8</td><td>执行代次 + 写入围栏</td><td>单写者锁 + <code>tmp</code> 文件原子 rename 发布</td></tr><tr><td>卡9</td><td>沙箱平台与三类负载基线</td><td>一条&quot;完整任务链基线脚本&quot;，每次改动跑一遍，记 P50/P95 与单次成功成本</td></tr><tr><td>卡10</td><td>Event Log / Checkpoint / Artifact</td><td><code>tasks.jsonl</code> + 每 N 步 <code>checkpoints/*.json</code> + <code>artifacts/</code> 内容哈希命名</td></tr><tr><td>卡11</td><td>分层工作区 + 不可变产物</td><td>Git 当快照与分支；<code>deliverables/</code> 单独目录，文件名带日期与哈希</td></tr><tr><td>卡12</td><td>记忆抽取/合并/遗忘管线</td><td><code>MEMORY.md</code>（内容 + 来源 + 最后确认时间），每月人工复核；删除=删行 + 重建索引</td></tr><tr><td>卡13</td><td>检索前权限过滤</td><td>每客户一个 collection 或 <code>docs/&lt;client&gt;/</code> 前缀过滤，禁止&quot;先召回后过滤&quot;</td></tr><tr><td>卡14</td><td>四档语义 + 六要素契约</td><td>只有两档：短调用同步；长任务&quot;提交 + 轮询 URL&quot;，配 <code>task_id</code> 与幂等键</td></tr><tr><td>卡15</td><td>通道键 + 手脑分离</td><td>按项目/客户分队列或至少分限流键；执行侧保持随时可重启，状态在文件里</td></tr><tr><td>卡16</td><td>多 Agent 团队 + 三种拓扑</td><td>保持单 Agent；子任务做成 Task Run；只在真并行时开第二个进程</td></tr><tr><td>卡17</td><td>共享上下文 + Task 停止条件</td><td>任务文件头部写目标、交付物、预算上限、停止条件；启动先读</td></tr><tr><td>卡18</td><td>原子预留的严格预算</td><td>每日 token 上限 + 超限自动降级/暂停 + 账单对账；达不到原子预留就声明&quot;软预算&quot;</td></tr><tr><td>卡19</td><td>跨层尝试预算</td><td>重试只在 SDK 一层，代理层关闭；<code>idempotency_key</code> + 总超时</td></tr><tr><td>卡20</td><td>网关默认拒绝 + 审批重新准入</td><td>工具白名单 + 参数 Schema + 危险操作人工二次确认；密钥只在环境变量</td></tr><tr><td>卡21</td><td>Task 分层账本</td><td>每次运行写 <code>usage.json</code>，月度 SQL 汇总&quot;每个任务多少钱&quot;</td></tr></tbody></table><hr><h2 id="_8-与现有页面的重叠与插入位置" tabindex="-1">8. 与现有页面的重叠与插入位置 <a class="header-anchor" href="#_8-与现有页面的重叠与插入位置" aria-label="Permalink to &quot;8. 与现有页面的重叠与插入位置&quot;">​</a></h2><p>现有页面（已读）：</p><ul><li><code>docs/zh/practice/index.md</code>：栏目目录页（<code>pageClass: catalog-page</code>，<code>navOrder: 1</code>），按&quot;先看形势 → 再决定怎么买&quot;两步组织，并声明&quot;不是本主题&quot;的路由规则。</li><li><code>docs/practice/ai-efficiency-practice.md</code>：英文路径下的实践页，讲&quot;AI 辅助需求到测试全流程&quot;&quot;Prompt 即需求文档&quot;&quot;人工审核节点&quot;&quot;效率提升 40%+&quot;。</li></ul><p><strong>重叠点</strong></p><table tabindex="0"><thead><tr><th>本页内容</th><th>现有页面</th><th>重叠性质</th></tr></thead><tbody><tr><td>卡5（人工审核节点）、卡9（验收口径与基线）</td><td><code>ai-efficiency-practice.md</code> 的&quot;人工审核节点&quot;&quot;提测质量改善&quot;&quot;效率提升 40%+&quot;</td><td>概念重叠：该页已提&quot;每个 AI 输出环节设置人工审核点&quot;，本页给出可验证的机制与指标；不复述该页的流程叙述</td></tr><tr><td>卡1（完成语义分层）、卡21（成功率 vs 完成率分别统计）</td><td><code>ai-efficiency-practice.md</code> 的&quot;效率提升显著&quot;</td><td>方法重叠：改进的是&quot;如何证明完成&quot;，不改动该页的结论数据</td></tr><tr><td>全页定位（工程机制/运行期）</td><td><code>index.md</code> 的&quot;不是本主题&quot;（工具教程、提示词、模型内部原理）</td><td>无重叠：本页属于工程落地，不属于被排除的三类</td></tr></tbody></table><p><strong>建议插入位置</strong></p><ol><li><code>docs/zh/practice/index.md</code>：在&quot;## 按决策顺序读&quot;中，&quot;### 2. 再决定怎么买&quot;之后插入一节： <code>### 3. 再决定怎么跑</code> — 链接本页（<code>/zh/practice/agent-runtime-practice</code>），一句话说明&quot;任务语义、沙箱、状态、协作、网关的工程机制与指标&quot;。同时把本页加入目录结构，保持 <code>index.md</code> 的 <code>next</code>（现为 Vibe Coding 报告）与本页 <code>prev/next</code> 串联一致。</li><li><code>ai-efficiency-practice.md</code>：在&quot;## 核心要点&quot;列表之后加一行交叉引用，例如&quot;工程机制（任务状态、沙箱、审批重新准入、成本归因）见中文实践页《Agent 运行期实践卡》&quot;。<strong>只加链接，不搬运内容</strong>，避免两页出现同一套指标定义。</li><li>本页 frontmatter 建议：<code>domain: practice</code>、<code>tags: [agent, runtime, engineering]</code>，与现有实践页保持同一命名空间；注意该实践页位于英文路径 <code>docs/practice/</code>，本页位于 <code>docs/zh/practice/</code>，<strong>两个目录并存</strong>（见第 10 节未决问题）。</li></ol><hr><h2 id="_9-建议落地顺序-可直接当-checklist" tabindex="-1">9. 建议落地顺序（可直接当 checklist） <a class="header-anchor" href="#_9-建议落地顺序-可直接当-checklist" aria-label="Permalink to &quot;9. 建议落地顺序（可直接当 checklist）&quot;">​</a></h2><ul><li><strong>第 1—2 周（语义先行）</strong>：卡1（执行 vs 完成两层字段）、卡3（外部写幂等键）、卡17 的停止条件写进任务模板。成本≈0，收益是止血。</li><li><strong>第 3—4 周（可恢复）</strong>：卡2 的状态机 + 权威状态文件、卡6 的工作区与会话恢复。指标：续行成功率、最老任务等待时长。</li><li><strong>第 5—6 周（成本与授权）</strong>：卡18（每日预算 + 超限降级）、卡19（单点重试）、卡20（工具白名单 + 危险操作二次确认）。</li><li><strong>第 7—8 周（规模化前）</strong>：卡9 的完整任务链基线脚本、卡14 的两档通信契约、卡21 的 <code>usage.json</code> 归因；此时再考虑是否需要队列/沙箱/网关等组件。</li><li><strong>规模化之后</strong>：卡10—卡13（状态、记忆、检索治理）、卡15—卡16（多 Agent 与通道治理），并按第 6 节的&quot;需按版本核验&quot;清单复核协议版本。</li></ul><h2 id="_10-未决问题" tabindex="-1">10. 未决问题 <a class="header-anchor" href="#_10-未决问题" aria-label="Permalink to &quot;10. 未决问题&quot;">​</a></h2><ol><li>现有实践页位于 <code>docs/practice/</code>（英文路径），目录页位于 <code>docs/zh/practice/</code>；本页按目录页命名空间放在 <code>docs/zh/practice/</code>，是否需要同步一份英文路径或重定向，需站点侧确认。</li><li>第 6 节 B 类的协议版本与发布日期来自原文，引用前需按官方规范复核。</li><li>第 6 节 A/C 类的内部案例数据未给出完整测试条件，不能直接用于对外承诺。</li></ol>`,86)])])}const p=o(l,[["render",e]]);export{k as __pageData,p as default};
